===EnsureUniqueTelephone.java===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose E.164 telephone is already used by another owner, so the
 * pair maps to a 409. Runs after {@link NormalizeOwnerTelephone} has canonicalized the
 * request's telephone to E.164, and before {@link BuildOwner} maps it to an entity. Existing
 * owners are compared on their E.164 telephone too, so formatting differences do not hide a
 * collision.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===EnsureUniqueEmail.java===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose lower-cased email is already used by another owner, so the
 * pair maps to a 409. Runs after {@link NormalizeOwnerEmail} has lower-cased the request's
 * email, and before {@link BuildOwner} maps it to an entity. Email is optional: a null or
 * blank value is left alone (no uniqueness to enforce). Existing owners are compared on their
 * lower-cased email too, so case differences do not hide a collision.
 */
public class EnsureUniqueEmail {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        String normalized = email.toLowerCase(Locale.ROOT);
        for (Owner existing : ownerRepository.findAll()) {
            String other = existing.getEmail();
            if (other != null && normalized.equals(other.toLowerCase(Locale.ROOT))) {
                throw new DuplicateEmailException(email);
            }
        }
    }
}
===EnsureUniqueHousehold.java===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose last name and address already belong to an existing owner,
 * so the pair maps to a 409 — unless the request opts in with {@code sharesHousehold=true},
 * declaring that the two owners share a household. Comparison is by {@link HouseholdKey}, so
 * case and whitespace differences do not hide a collision.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = HouseholdKey.of(request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (key.equals(HouseholdKey.of(existing.getLastName(), existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===NormalizeOwnerTelephone.java===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the telephone on a create request to E.164 form (see {@link TelephoneNormalizer}).
 * Stores the E.164 value back on the request (mutating the shared {@code @Val} object) so
 * {@link BuildOwner} and the response carry it; rejects with {@link InvalidTelephoneException}
 * (400) when the number cannot form valid E.164 or its national-number length is wrong for the
 * country code (see {@link E164CountryLength}). Runs after {@link ValidateNewOwner} has
 * confirmed the field is present.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String raw = request.getTelephone();
        String e164 = TelephoneNormalizer.toE164(raw);
        if (e164 == null || !E164CountryLength.isNationalLengthValid(e164)) {
            throw new InvalidTelephoneException(raw);
        }
        request.setTelephone(e164);
    }
}
===TelephoneNormalizer.java===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Shared telephone normalization to E.164 form. Strips spaces, dashes and brackets, then:
 * keeps a leading '+' and country code when present; otherwise assumes country code '+61'
 * and drops a single leading '0' from the national digits. The result must carry 8 to 15
 * digits after the '+'. Used both to canonicalize an incoming request's telephone and to
 * compare it against the telephones already stored on other owners.
 */
final class TelephoneNormalizer {

    private TelephoneNormalizer() {
    }

    /**
     * Returns the E.164 representation of {@code raw} (a leading '+' followed by 8-15
     * digits), or {@code null} when it cannot form a valid E.164 number.
     */
    static String toE164(String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        } else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        return "+" + digits;
    }
}
