package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Canonical key identifying a household by its owner's last name and address. Two owners
 * belong to the same household when their keys are equal: last name and address are compared
 * case-insensitively with leading/trailing and repeated whitespace collapsed to a single
 * space, so incidental formatting differences do not hide a match.
 */
final class HouseholdKey {

    private HouseholdKey() {
    }

    static String of(String lastName, String address) {
        return normalize(lastName) + '�' + normalize(address);
    }

    /**
     * Stable identifier shared by every owner of a household: the SHA-256 hex digest of the
     * canonical {@link #of(String, String) key}. Purely derived from last name and address, so
     * two owners in the same household always get the same value regardless of creation order.
     */
    static String id(String lastName, String address) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256")
                    .digest(of(lastName, address).getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(Character.forDigit((b >> 4) & 0xF, 16));
            hex.append(Character.forDigit(b & 0xF, 16));
        }
        return hex.toString();
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
===AddressNormalizer===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Shared address normalization: trims and collapses runs of whitespace to a single space,
 * upper-cases, and expands common street-type abbreviations token by token (ST -> STREET,
 * RD -> ROAD, AVE -> AVENUE). Used both to canonicalize an incoming request's address (the
 * stored and returned form) and to compare it against the addresses already held on other
 * owners, so incidental formatting or abbreviation differences do not hide a match.
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    /**
     * Returns the normalized form of {@code raw}: upper-case, single-spaced tokens with known
     * abbreviations expanded. A {@code null} address yields an empty string, so a value that is
     * blank after normalization is detectable as blank.
     */
    static String normalize(String raw) {
        if (raw == null || raw.isBlank()) {
            return "";
        }
        StringBuilder normalized = new StringBuilder();
        for (String token : raw.trim().split("\\s+")) {
            String upper = token.toUpperCase(Locale.ROOT);
            if (normalized.length() > 0) {
                normalized.append(' ');
            }
            normalized.append(ABBREVIATIONS.getOrDefault(upper, upper));
        }
        return normalized.toString();
    }
}
