package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Canonical identity of an owner for duplicate detection. The single derived key
 * {@code identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId}
 * consolidates what used to be three independent uniqueness checks (telephone, email and
 * household): two owners are duplicates only when their whole keys are equal. Because the
 * telephone is part of the key, members of the same household with different telephones get
 * different keys and are both allowed.
 *
 * <p>The parts are canonicalized the same way as the create pipeline itself — telephone via
 * {@link TelephoneNormalizer#toE164(String)}, email lower-cased, household via
 * {@link HouseholdKey#id(String, String)} — so the key is computed identically for an incoming
 * request and for an already-stored owner regardless of incidental formatting differences.
 */
final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** Identity key of a create request. */
    static String of(OwnerFieldsDto request) {
        return of(request.getTelephone(), request.getEmail(), request.getLastName(), request.getAddress());
    }

    /** Identity key of an existing owner. */
    static String of(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress());
    }

    private static String of(String telephone, String email, String lastName, String address) {
        String normalizedTelephone = TelephoneNormalizer.toE164(telephone);
        String normalizedEmail = (email == null) ? "" : email.trim().toLowerCase(Locale.ROOT);
        return (normalizedTelephone == null ? "" : normalizedTelephone)
                + '|' + normalizedEmail
                + '|' + HouseholdKey.id(lastName, address);
    }
}

